document.querySelectorAll('.service').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.service').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector('select').value=[...document.querySelector('select').options].some(o=>o.value===b.dataset.service)?b.dataset.service:'Первичная консультация';document.querySelector('#book').scrollIntoView({behavior:'smooth'})}));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('show')}));document.querySelectorAll('.reveal').forEach(x=>io.observe(x));const d=document.querySelector('dialog');document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();if(e.currentTarget.reportValidity()){d.showModal();e.currentTarget.reset()}});document.querySelectorAll('.close,.ok').forEach(x=>x.addEventListener('click',()=>d.close()));
